/* Level 13 (Gemlik Base) code following sound; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x002994D0 (was sound_002994D0.c). */
#include "common.h"
#include "include_asm.h"

typedef struct {
    char pad0[0x75];
    unsigned char flags;
} Level13SoundEffectTarget;

extern char hero_globals_base[];

/* Enable a sound effect and copy its 16-byte parameter vector. */
int set_voice_position(int index, const void *vector) {
    int offset = index * 0x70;
    char *base = hero_globals_base + 0x1D;
    char *vector_base = base + 0xA0;
    Level13SoundEffectTarget *effect = (Level13SoundEffectTarget *)(base + offset);
    effect->flags |= 0x40;
    qcopy(vector_base + offset, vector);
    return 1;
}
